// Image preview, generated by Rust (works for HEIC, TGA, TIFF… that the webview can't show)
// and only once the card scrolls into view.
import { memo, useEffect, useRef, useState } from "react";
import { api } from "../../lib/api";
import type { FileInfo } from "../../lib/types";

/** path → blob URL (as a promise, so two cards showing the same file share one request). */
const cache = new Map<string, Promise<string | null>>();

function load(path: string): Promise<string | null> {
  let p = cache.get(path);
  if (!p) {
    p = api
      .thumbnail(path)
      .then((buf) => URL.createObjectURL(new Blob([buf])))
      .catch(() => null);
    cache.set(path, p);
  }
  return p;
}

/** Free the previews of files that left the list (memory would otherwise grow drop after drop). */
export function releaseThumbnails(paths: Iterable<string>) {
  for (const path of paths) {
    const p = cache.get(path);
    if (!p) continue;
    cache.delete(path);
    p.then((url) => url && URL.revokeObjectURL(url));
  }
}

export const Thumbnail = memo(function Thumbnail({ file }: { file: FileInfo }) {
  const ref = useRef<HTMLDivElement>(null);
  const [url, setUrl] = useState<string | null>(null);
  const canPreview = (file.kind === "image" || file.format === "pdf") && file.operations.length > 0;

  useEffect(() => {
    if (!canPreview || !ref.current) return;
    let alive = true;
    const el = ref.current;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        io.disconnect();
        load(file.path).then((u) => alive && setUrl(u));
      },
      { rootMargin: "200px" },
    );
    io.observe(el);
    return () => {
      alive = false;
      io.disconnect();
    };
  }, [file.path, canPreview]);

  return (
    <div
      ref={ref}
      className="relative h-14 w-14 shrink-0 overflow-hidden rounded-lg bg-surface-2"
      style={url ? { backgroundImage: "repeating-conic-gradient(#8883 0 25%, transparent 0 50%)", backgroundSize: "12px 12px" } : undefined}
    >
      {url && <img src={url} alt="" className="h-full w-full object-cover" draggable={false} />}
      {!url && (file.kind === "audio" || file.kind === "video") && (
        <span aria-hidden className="absolute inset-0 flex items-center justify-center pb-2 text-2xl text-muted">
          {file.kind === "audio" ? "♪" : "▶"}
        </span>
      )}
      <span className="absolute bottom-0.5 left-0.5 rounded bg-black/70 px-1 text-[10px] font-bold tracking-wide text-white">
        {file.formatLabel ?? "?"}
      </span>
    </div>
  );
});
